import threading

a, b = threading.Lock(), threading.Lock()
barrier = threading.Barrier(2)
done_try = threading.Barrier(2)
results = []

def worker(first, second, name):
    with first:
        barrier.wait()                       # both hold one lock now
        got = second.acquire(timeout=0.3)    # circular wait: would hang without timeout
        done_try.wait()                      # both finish trying before anyone releases
        if got:
            second.release(); results.append(name + " ok")
        else:
            results.append(name + " timed out")

def run(pairs):
    ts = [threading.Thread(target=worker, args=p) for p in pairs]
    for t in ts: t.start()
    for t in ts: t.join()

run([(a, b, "T1"), (b, a, "T2")])           # opposite order -> deadlock
print("opposite order:", sorted(results))

# Fix: always take locks in a global order (here: by id of the lock).
def ordered(x, y):
    return sorted([x, y], key=id)

results.clear()
def safe(name):
    f, s = ordered(a, b)
    with f:
        with s:
            results.append(name + " ok")
ts = [threading.Thread(target=safe, args=(n,)) for n in ("T1", "T2")]
for t in ts: t.start()
for t in ts: t.join()
print("global order:  ", sorted(results))

