import sys, threading, time, traceback

a, b = threading.Lock(), threading.Lock()
ready = threading.Barrier(3)

def worker(first, second):
    with first:
        ready.wait()
        second.acquire()           # hangs forever: classic deadlock

def waits_on_lock_a():
    worker(a, b)
def waits_on_lock_b():
    worker(b, a)

for fn in (waits_on_lock_a, waits_on_lock_b):
    threading.Thread(target=fn, daemon=True).start()
ready.wait()
time.sleep(0.2)

# Like py-spy dump / faulthandler: print where each thread is stuck.
names = {t.ident: t.name for t in threading.enumerate()}
for ident, frame in sorted(sys._current_frames().items(), key=lambda kv: names.get(kv[0], "")):
    if ident == threading.get_ident():
        continue
    stack = [f.name for f in traceback.extract_stack(frame)]
    print("stuck thread stack:", " -> ".join(stack[-3:]))
